let $injector = ctx.$scope.$injector;
let userService = $injector.get(ctx.servicesMap.get('userService')); 

const roleFromLocalStorage = localStorage.getItem("role");
let showButton = false;

if (!roleFromLocalStorage) {
    userService.getUserInfo(ctx.currentUser.userId).subscribe(response => {
        const role = response.groups.some((element) => element.name === "Tenant Administrators") ? "Admin" : "Viewer";

        showButton = role === "Admin";

        localStorage.setItem("role", role);
    });
} else {
    showButton = roleFromLocalStorage === "Admin";
}

return `
<div class="dashboard-header-container">
    <div class="title">Overview</div>
    <button id="addNewDevice" class="create-asset-button" *ngIf="${showButton}">+ New device</button>
</div>
`

